class Solution {
public:
    int maximumSum(vector<int>& arr) {
        int keep = arr[0], skipped = 0, best = arr[0];
        for (int i = 1; i < (int)arr.size(); i++) {
            skipped = max(skipped + arr[i], keep);
            keep = max(keep + arr[i], arr[i]);
            best = max({best, keep, skipped});
        }
        return best;
    }
};
